// CSD_RATIONALE_BEGIN
// Attempt 49: Return to attempt 43's proven structure (52% best result) and
// replace the manual GroupBoostedConstrainedStep loop with a single call to
// RegenerateUnitOnGroundingFailure for Phase 3.
//
// Root cause of attempt 43's 141/300 failures:
//   The model generates syntactically valid SQL but uses hallucinated table
//   aliases and column names that are not in the schema (e.g., `v.name` for
//   visitor.name, `dp.degree_summary_name` for the actual column). These are
//   parser-VALID (SQL grammar allows arbitrary aliases) but semantically wrong.
//   GroupBoostedConstrainedStep softly prefers schema tokens but cannot prevent
//   the model from choosing alias forms.
//
// Fix: Phase 3 calls RegenerateUnitOnGroundingFailure with the bulk token
//   budget. This helper generates tokens, detects at each schema-symbol boundary
//   whether the identifier is grounded in the prompt (schema), and rolls back
//   with penalty to resample if it finds a hallucinated identifier. Since we
//   enter Phase 3 with currentConstrainedOut == [] (immediately after
//   OpenConstrainedSpan), there is no content to roll back into; the helper only
//   generates forward, so |resultConstrained| <= budget3 is guaranteed (each of
//   budget3 steps adds at most 1 token, no prior content to exceed the bound).
//
// Preserved from attempt 43 (do NOT regress):
//   - 5-step preamble to let model emit "SQL: " prefix
//   - Force-open Phase 2 (always ensures << even if model doesn't emit it)
//   - RenderedEndsWith (not next == "<<") for delimiter detection
//   - CloseSpanWithinBudget Phase 4 with budget ≤ 100
//   - Same guidance text (attempt 47/48 guidance changes both hurt)
//
// Key change vs attempt 48: Remove the |currentConstrainedOut| >= 15 guard
// (that caused 26.3% regression) and replace manual loop with
// RegenerateUnitOnGroundingFailure.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (preamble):
//   UnconstrainedStep returns EOS → insideConstrainedOut stays false, implication
//   vacuous. Non-EOS: generated grows by 1. On RenderedEndsWith("<<") we set
//   currentConstrainedOut := [] which satisfies IsValidPrefix([]) by precondition.
//   Otherwise state unchanged; invariant preserved from loop entry.
//
// Phase 2 (OpenConstrainedSpan):
//   Only runs when !insideConstrainedOut. Helper sets currentConstrainedOut := [];
//   IsValidPrefix([]) holds by precondition. insideConstrainedOut := true. ✓
//
// Phase 3 (RegenerateUnitOnGroundingFailure):
//   Only runs when insideConstrainedOut. Postcondition of
//   RegenerateUnitOnGroundingFailure guarantees resultConstrained is always
//   parser-valid. Setting currentConstrainedOut := rc preserves the invariant.
//   insideConstrainedOut stays true (helper does not close the span). ✓
//
// Phase 4 (close):
//   CloseConstrainedSpan: sets insideConstrainedOut := false → implication vacuously
//   true; sets currentConstrainedOut := []. ✓
//   CloseSpanWithinBudget: postcondition guarantees insideOut ==>
//   parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each iteration: UnconstrainedStep costs 1 step; appends ≤ 1 non-EOS
//   token. |generated| grows by ≤ 1, steps grows by exactly 1. ✓
//
// Phase 2: OpenConstrainedSpan appends exactly "<<" (1 token) and costs 1 step.
//   Net 1:1. ✓
//
// Phase 3: steps += budget3. |generated| = |stablePrefix| + |rc| = |old_generated|
//   + |rc|. Since Phase 3 runs only when currentConstrainedOut == [] (no content to
//   roll back), the helper only generates forward: each of budget3 steps adds ≤ 1
//   token, so |rc| <= budget3. Hence |generated| <= |generatedPrefix| + old_steps
//   + budget3 = |generatedPrefix| + steps. ✓
//
// Phase 4a (CloseConstrainedSpan): steps += 1; appends ≤ 1 ">>" token. ≤ 1:1. ✓
// Phase 4b (CloseSpanWithinBudget): steps += cb; postcondition |generatedOut| <=
//   |generated| + cb; net ≤ cb:cb. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if model did not emit it naturally
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Grounding-aware constrained SQL generation.
// Precondition: currentConstrainedOut == [] (either set by preamble detection or
// by OpenConstrainedSpan just above). Starting from an empty constrained prefix,
// RegenerateUnitOnGroundingFailure only generates forward (no rollback source);
// each of budget3 steps adds at most 1 token, so |rc| <= budget3.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining > 100 {
    var budget3 := remaining - 100;
    // stablePrefix is the full generated (since currentConstrainedOut == [])
    var stablePrefix := generated;
    var rc := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, prompt, currentConstrainedOut, eosToken, budget3, 3, 10
    );
    // rc is parser-valid (postcondition). |rc| <= budget3 (starts from empty).
    currentConstrainedOut := rc;
    generated := stablePrefix + rc;
    steps := steps + budget3;
  }
}

// Phase 4: Close the constrained span.
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining4 := maxSteps - steps;
    var cb : nat;
    if remaining4 <= 100 {
      cb := remaining4;
    } else {
      cb := 100;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, cb
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + cb;
  }
}

cost := steps;

